function CreateBatch(){const nav=useNavigate(),[hives,setHives]=useState([]),[form,setForm]=useState({hiveId:new URLSearchParams(useLocation().search).get('hive')||'HC-001',honeyType:'Multi-floral Honey',quantity:20,harvestDate:'2026-09-10',origin:'Haryana, India'}),[msg,setMsg]=useState('');useEffect(()=>{api('/hives').then(x=>setHives(Array.isArray(x)?x.map(normalizeHive):[]))},[]);async function submit(e){e.preventDefault();try{const b=await api('/batches',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(form)});setMsg(`Batch ${b.batchId} created successfully.`);setTimeout(()=>nav(`/app/batches/${b.batchId}`),600)}catch(e){setMsg(e.message)}}return <><PageTitle eyebrow="TRACEABILITY" title="Create Honey Batch" desc="Create a new harvest record from a registered hive."/><form className="panel formPanel" onSubmit={submit}><div className="formGrid"><label>Select Hive<select value={form.hiveId} onChange={e=>setForm({...form,hiveId:e.target.value})}>{(Array.isArray(hives)?hives:[]).map(h=><option key={h.id}>{h.id}</option>)}</select></label><label>Honey Type<select value={form.honeyType} onChange={e=>setForm({...form,honeyType:e.target.value})}><option>Multi-floral Honey</option><option>Wildflower Honey</option><option>Mustard Honey</option><option>Eucalyptus Honey</option></select></label><label>Quantity (kg)<input type="number" min="0.1" step="0.1" value={form.quantity} onChange={e=>setForm({...form,quantity:Number(e.target.value)})}/></label><label>Harvest Date<input type="date" value={form.harvestDate} onChange={e=>setForm({...form,harvestDate:e.target.value})}/></label><label className="full">Origin<input value={form.origin} onChange={e=>setForm({...form,origin:e.target.value})}/></label></div><button className="goldBtn" type="submit">Create batch <ArrowRight size={17}/></button>{msg&&<div className="successBox">{msg}</div>}</form></>}
function BatchDetails(){const {id}=useParams();const auth=useAuth();const [b,setB]=useState(null),[integrity,setIntegrity]=useState(null),[workflow,setWorkflow]=useState(null),[error,setError]=useState('');useEffect(()=>{Promise.allSettled([api(`/batches/${id}`),api(`/batches/${id}/workflow`),api(`/batches/${id}/integrity`)]).then(([a,w,c])=>{if(a.status==='fulfilled')setB(normalizeBatch(a.value?.batch||a.value));else setError(a.reason?.message||'Batch could not be loaded');if(w.status==='fulfilled')setWorkflow(w.value);if(c.status==='fulfilled')setIntegrity(c.value)})},[id]);if(error)return <><PageTitle eyebrow="TRACEABILITY" title="Batch unavailable" desc={error}/><div className="errorBox">The selected batch could not be loaded. Return to Honey Batches and try again.</div></>;if(!b)return <Loading/>;return <><Link className="backLink" to="/app/batches">← Back to Honey Batches</Link><PageTitle eyebrow="TRACEABILITY RECORD" title={b.batchId} desc={`${b.honeyType} · ${b.hiveId}`} action={<Status text={b.status}/>}/><div className="batchDetailGrid"><section className="panel"><div className="detailRows"><p><span>Honey type</span><b>{b.honeyType}</b></p><p><span>Quantity</span><b>{b.quantity} kg</b></p><p><span>Harvest date</span><b>{b.harvestDate}</b></p><p><span>Origin</span><b>{b.origin}</b></p><p><span>Integrity hash</span><b className="greenText">{b.integrityHash||b.integrity_hash?'Verified':'—'}</b></p></div></section><section className="panel passportLink"><ShieldCheck size={28}/><small>PUBLIC CONSUMER DASHBOARD</small><h3>Show the complete journey.</h3><p>The consumer view contains harvesting, processing, packaging, verification and blockchain-backed record integrity.</p><div style={{display:'flex',gap:10,flexWrap:'wrap'}}><Link className="goldBtn" to={`/consumer/${b.batchId}`}>Open consumer dashboard <ArrowRight size={16}/></Link>{(auth?.role==='packaging'||auth?.role==='admin')&&<Link className="outlineBtn" to={`/app/qr?batch=${encodeURIComponent(b.batchId)}`}>Generate / view QR <ScanLine size={16}/></Link>}</div></section></div><section className="panel" style={{marginTop:20}}><div className="panelHeading"><div><small>LIVE WORKFLOW</small><h2>Journey state</h2></div><Status text={b.status||'Harvested'}/></div><WorkflowSteps workflow={workflow}/></section>{integrity&&<section className="panel" style={{marginTop:20}}><div className="panelHeading"><div><small>RECORD INTEGRITY VERIFICATION</small><h2>Journey record verification</h2></div><Status text={integrity.chainValid?'Verified':'Review'}/></div><div className="statsGrid"><Stat icon={ShieldCheck} label="Integrity" value={integrity.chainValid?'Verified':'Review'} sub="Hash-linked transition record"/><Stat icon={Box} label="Events" value={integrity.eventCount??0} sub="Recorded transition events"/></div><p className="iotExplain">The blockchain page is intentionally not exposed as an Admin workspace page. Verification remains attached to the live transition record.</p></section>}</>}

function ProcessorIncoming(){const [batches,setBatches]=useState([]);useEffect(()=>{api('/batches').then(x=>setBatches(Array.isArray(x)?x.map(normalizeBatch):[])).catch(()=>{})},[]);const list=batches.filter(b=>['Harvested','Health Assessed'].includes(b.status));return <><PageTitle eyebrow="PROCESSOR" title="Incoming Batches" desc="Harvested batches become available here only after the hive health assessment is recorded."/><BatchTable batches={list}/>{!list.length&&<div className="emptyState"><b>No batch is ready for processing</b><p>A beekeeper must create the batch and complete the health assessment first.</p></div>}</>}
function ProcessorProcessing(){const [batches,setBatches]=useState([]),[selected,setSelected]=useState(null),[form,setForm]=useState({process_type:'Standard Processing',input_quantity:'',output_quantity:'',quality_notes:''}),[error,setError]=useState(''),[busy,setBusy]=useState(false);async function load(){try{const x=await api('/batches');setBatches(Array.isArray(x)?x.map(normalizeBatch):[])}catch(e){setError(e.message)}}useEffect(()=>{load()},[]);async function open(id){try{setSelected(await api(`/batches/${encodeURIComponent(id)}`));setError('')}catch(e){setError(e.message)}}async function submit(e){e.preventDefault();if(!selected)return;setBusy(true);try{await api('/processing',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({batch_id:selected.batch.batch_id,process_type:form.process_type,input_quantity:Number(form.input_quantity||selected.batch.quantity),output_quantity:Number(form.output_quantity||selected.batch.quantity),quality_notes:form.quality_notes})});await load();await open(selected.batch.batch_id)}catch(e){setError(e.message)}finally{setBusy(false)}}async function verify(){if(!selected)return;setBusy(true);try{await api(`/processing/${encodeURIComponent(selected.batch.batch_id)}/verify`,{method:'POST'});await load();await open(selected.batch.batch_id)}catch(e){setError(e.message)}finally{setBusy(false)}}return <><PageTitle eyebrow="PROCESSOR" title="Processing Records" desc="Select a production batch, record the actual processing, then verify it."/>{error&&<div className="errorBox" style={{marginBottom:16}}>{error}</div>}<div className="eventGrid">{batches.map(b=><button className="panel eventCard clickableCard" key={b.batchId} onClick={()=>open(b.batchId)}><div className="featureIcon"><Factory size={19}/></div><small>PRODUCTION BATCH</small><h3>{b.batchId}</h3><p>{b.honeyType||'Honey'} · {b.quantity??'—'} kg · Hive {b.hiveId||'—'}</p><span className="cardAction">Open processing record <ArrowRight size={14}/></span></button>)}{!batches.length&&<div className="emptyState"><b>No batches available</b><p>Only live database batches are shown here.</p></div>}</div>{selected&&<section className="panel batchRecordPanel"><div className="panelHeading"><div><small>PROCESSING RECORD</small><h2>{selected.batch?.batch_id}</h2><p>{selected.batch?.honey_type||'Honey'} · Source hive {selected.batch?.hive_code||'—'}</p></div><Status text={selected.batch?.status||'Recorded'}/></div><div className="detailRows">{[['Batch ID',selected.batch?.batch_id],['Source hive',selected.batch?.hive_code],['Honey type',selected.batch?.honey_type],['Quantity',selected.batch?.quantity!=null?`${selected.batch.quantity} kg`:null],['Harvest date',selected.batch?.harvest_date],['Origin',selected.batch?.origin]].map(([k,v])=><p key={k}><span>{k}</span><b>{v||'—'}</b></p>)}</div>{['Harvested','Health Assessed'].includes(selected.batch?.status)&&<form className="panel formPanel" onSubmit={submit} style={{marginTop:18}}><div className="formGrid"><label>Process type<input value={form.process_type} onChange={e=>setForm({...form,process_type:e.target.value})}/></label><label>Input quantity (kg)<input type="number" step="0.1" value={form.input_quantity} onChange={e=>setForm({...form,input_quantity:e.target.value})}/></label><label>Output quantity (kg)<input type="number" step="0.1" value={form.output_quantity} onChange={e=>setForm({...form,output_quantity:e.target.value})}/></label><label className="full">Quality notes<textarea value={form.quality_notes} onChange={e=>setForm({...form,quality_notes:e.target.value})}/></label></div><button className="goldBtn" disabled={busy}>{busy?'Saving…':'Record Processing'} <ArrowRight size={16}/></button></form>}{selected.batch?.status==='Processed'&&<button className="goldBtn" onClick={verify} disabled={busy}>{busy?'Verifying…':'Verify Processing'} <ShieldCheck size={16}/></button>}<div className="publicTimeline">{(Array.isArray(selected.events)?selected.events:[]).map((x,i)=><div key={`${x.event_type}-${i}`}><div className="publicDot"><Check size={14}/></div><span><small>{x.event_date||'Recorded'}</small><b>{x.event_type}</b><p>{x.description||'Event recorded for this production batch.'}</p><em>{x.actor||'Stakeholder'}</em></span></div>)}</div></section>}</>}

function ProcessorTraceability(){const [batches,setBatches]=useState([]),[selected,setSelected]=useState(null);useEffect(()=>{api('/batches').then(x=>setBatches(Array.isArray(x)?x.map(normalizeBatch):[])).catch(()=>{})},[]);async function open(id){try{setSelected(await api(`/batches/${encodeURIComponent(id)}`))}catch{setSelected(null)}}return <><PageTitle eyebrow="PROCESSOR" title="Traceability" desc="Select a batch to inspect its complete production journey."/><div className="tablePanel"><div className="tableHeader"><span>Batch ID</span><span>Honey Type</span><span>Source Hive</span><span>Status</span><span>Open</span></div>{batches.map(b=><button className="tableRow" key={b.batchId} onClick={()=>open(b.batchId)}><span><i className="tableIcon traceIcon"><Factory size={17}/></i><b>{b.batchId}</b></span><span>{b.honeyType||'—'}</span><span>{b.hiveId||'—'}</span><span><Status text={b.status||'Recorded'}/></span><span>View journey <ArrowRight size={14}/></span></button>)}</div>{selected&&<section className="panel journeyDetail"><div className="panelHeading"><div><small>FULL PRODUCTION JOURNEY</small><h2>{selected.batch?.batch_id}</h2><p>{selected.batch?.honey_type} · Hive {selected.batch?.hive_code}</p></div><ShieldCheck size={20}/></div><div className="journeySteps">{(Array.isArray(selected.events)?selected.events:[]).map((x,i)=><div key={`${x.event_type}-${i}`} className="journeyStep"><div className="journeyIcon">{i===0?<Hexagon size={18}/>:x.event_type?.toLowerCase().includes('process')?<Factory size={18}/>:x.event_type?.toLowerCase().includes('pack')?<Package size={18}/>:<Check size={18}/>}</div><div><small>{x.event_date||'Recorded'}</small><b>{x.event_type}</b><p>{x.description||'Production event recorded.'}</p><em>{x.actor||'Stakeholder'}</em></div></div>)}</div></section>}</>}
function PackagingReady(){const [batches,setBatches]=useState([]);useEffect(()=>{api('/batches').then(x=>setBatches(Array.isArray(x)?x.map(normalizeBatch):[])).catch(()=>{})},[]);const list=batches.filter(b=>['Ready for Packaging','Packaged','Awaiting Admin Validation','Validated'].includes(b.status));return <><PageTitle eyebrow="PACKAGING" title="Ready to Package" desc="Only processor-verified batches can enter the packaging queue."/><BatchTable batches={list}/>{!list.length&&<div className="emptyState"><b>No batch is ready for packaging</b><p>Processing must be completed and verified by the processor first.</p></div>}</>}
function Production(){
 const qs=new URLSearchParams(useLocation().search);
 const [hives,setHives]=useState([]),[id,setId]=useState(qs.get('hive')||''),[form,setForm]=useState({environmental_temperature:'',relative_humidity:'',hive_temperature:'',hive_humidity:'',wind_speed:'',total_hive_weight:'',prediction_date:new Date().toISOString().slice(0,10)}),[data,setData]=useState(null),[busy,setBusy]=useState(false),[error,setError]=useState('');
 useEffect(()=>{api('/hives').then(x=>{const hs=Array.isArray(x)?x:[];setHives(hs);if(!id&&hs[0])setId(hs[0].id)}).catch(e=>setError(e.message))},[]);
 useEffect(()=>{const h=hives.find(x=>(x.hive_code||x.id)===id);if(h)setForm(v=>({...v,hive_temperature:v.hive_temperature||h.temperature||'',hive_humidity:v.hive_humidity||h.humidity||'',total_hive_weight:v.total_hive_weight||h.weight||''}))},[id,hives]);
 const set=(k,v)=>setForm(x=>({...x,[k]:v}));
 async function run(e){e.preventDefault();setBusy(true);setError('');try{const r=await api('/production/predict',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({hive_id:id,...Object.fromEntries(Object.entries(form).map(([k,v])=>[k,['prediction_date'].includes(k)?v:Number(v)]))})});setData(r)}catch(e){setError(e.message)}finally{setBusy(false)}}
 return <><PageTitle eyebrow="BEEKEEPER · PRODUCTION INTELLIGENCE" title="Honey Production Prediction" desc="Use the trained Random Forest model with current hive and environmental inputs. No demo production values are shown."/>
 <form className="panel formPanel" onSubmit={run}><div className="panelHeading"><div><small>TRAINED MODEL INPUTS</small><h2>Predict production</h2></div><BarChart3 size={19}/></div><div className="formGrid"><label>Select Hive<select value={id} onChange={e=>setId(e.target.value)} required>{!id&&<option value="">Select a hive</option>}{hives.map(h=><option key={h.id} value={h.id}>{h.id}</option>)}</select></label><label>Prediction Date<input type="date" value={form.prediction_date} onChange={e=>set('prediction_date',e.target.value)} required/></label><label>Environmental Temperature (°C)<input type="number" step="0.01" value={form.environmental_temperature} onChange={e=>set('environmental_temperature',e.target.value)} required/></label><label>Relative Humidity (%)<input type="number" step="0.01" value={form.relative_humidity} onChange={e=>set('relative_humidity',e.target.value)} required/></label><label>Hive Temperature (°C)<input type="number" step="0.01" value={form.hive_temperature} onChange={e=>set('hive_temperature',e.target.value)} required/></label><label>Hive Humidity (%)<input type="number" step="0.01" value={form.hive_humidity} onChange={e=>set('hive_humidity',e.target.value)} required/></label><label>Wind Speed (km/h)<input type="number" step="0.01" value={form.wind_speed} onChange={e=>set('wind_speed',e.target.value)} required/></label><label>Total Hive Weight (kg)<input type="number" step="0.01" min="0" value={form.total_hive_weight} onChange={e=>set('total_hive_weight',e.target.value)} required/></label></div>{error&&<div className="errorBox">{error}</div>}<button className="goldBtn" disabled={busy||!id}>{busy?'Predicting…':'Predict Honey Production'} <Sparkles size={17}/></button></form>
 {data&&<><section className="panel productionTop"><div className="predictionHero"><Sparkles size={28}/><small>MODEL PREDICTION</small><b>{data.predictedProduction} kg</b><span>{data.predictionDate} · {data.model?.model||'Trained production model'}</span><Status text={data.riskLevel}/></div><div className="readingRows"><p><span>Historical average</span><b>{data.historicalAverage!=null?`${data.historicalAverage} kg`:'Not available'}</b></p><p><span>Change vs baseline</span><b>{data.changePercent!=null?`${data.changePercent}%`:'Not available'}</b></p><p><span>Assessment</span><b>{data.explanation}</b></p></div></section><div className="explanationGrid"><section className="panel"><div className="panelHeading"><div><small>PRODUCTION GOVERNANCE</small><h2>Possible reasons</h2></div><AlertTriangle size={19}/></div>{data.reasons?.length?data.reasons.map(r=><div className="reason" key={r.title}><div className="reasonIcon"><Activity size={16}/></div><span><b>{r.title}</b><p>{r.detail}</p></span></div>):<div className="emptyState"><b>No specific reason isolated</b><p>Use the model inputs and recent hive observations together.</p></div>}</section><section className="panel"><div className="panelHeading"><div><small>RECOMMENDED ACTIONS</small><h2>What to do next</h2></div><Leaf size={19}/></div>{(data.recommendedActions||[]).map((a,i)=><div className="actionRow" key={i}><span>{i+1}</span><p>{a}</p></div>)}</section></div></>}
 </>}
function Status({text}){return <span className={`status ${text?.toLowerCase().replaceAll(' ','-')}`}>{text}</span>}
function WorkflowSteps({workflow}){const steps=Array.isArray(workflow?.steps)?workflow.steps:[];const icons={hive:Hexagon,harvest:Leaf,health:HeartPulse,processing:Factory,packaging:Package,admin:ShieldCheck,qr:ScanLine};return <div className="publicTimeline">{steps.map((x,i)=>{const I=icons[x.key]||Check;return <div key={x.key}><div className={`publicDot ${x.complete?'last':''}`}><I size={14}/></div><span><small>{x.complete?'Completed':'Pending'}</small><b>{x.label}</b><p>{x.complete?'Recorded in the live workflow ledger.':'Waiting for the responsible stakeholder action.'}</p></span></div>})}</div>}
function HiveSelector({hives,value,onChange,showDetails=true,label="Select Hive"}){
 const selected=hives.find(h=>h.id===value);
 return <div className="hiveSelectorBlock"><label>{label}<span className="selectWrap"><select value={value||''} onChange={e=>onChange(e.target.value)}>{!value&&<option value="">Select a hive</option>}{(Array.isArray(hives)?hives:[]).map(h=><option key={h.id} value={h.id}>{h.id}</option>)}</select></span></label>{showDetails&&selected&&<div className="selectedHiveDetails"><div className="selectedHiveHeading"><span className="hiveIcon"><Hexagon size={18}/></span><div><small>SELECTED HIVE</small><h3>{selected.id}</h3><p>{selected.location||'Location not recorded'}</p></div><Status text={selected.healthStatus||selected.status}/></div><div className="selectedHiveGrid">{hiveDetails(selected).map(([k,v])=><div key={k}><small>{k}</small><b>{v}</b></div>)}</div></div>}</div>
}
