 async function analyze(e){e.preventDefault();if(!file||!id)return;setBusy(true);setError('');try{const fd=new FormData();fd.append('hive_id',id);fd.append('image',file);if(sensor.temperature!=='')fd.append('temperature',sensor.temperature);if(sensor.humidity!=='')fd.append('humidity',sensor.humidity);if(sensor.weight!=='')fd.append('weight',sensor.weight);const r=await api('/bee-health/analyze',{method:'POST',body:fd});setResult(r);await loadResults()}catch(e){setError(e.message||'Analysis failed')}finally{setBusy(false)}}
 const mine=saved.filter(x=>x.hiveId===id);
